class Solution {
  public int[] longestSpecialPath(int[][] edges, int[] nums) {
    int n = nums.length;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int[] occ1 = new int[50_001], occ2 = new int[50_001];
    java.util.Arrays.fill(occ1, -1);
    java.util.Arrays.fill(occ2, -1);
    long[] dist = new long[n];
    int[] stNode = new int[n], stPar = new int[n], stPtr = new int[n];
    int[] sO1 = new int[n], sO2 = new int[n], sT1 = new int[n], sT2 = new int[n];
    int top1 = 0, top2 = 0;
    long bestLen = 0;
    int bestNodes = 1;
    stNode[0] = 0;
    stPar[0] = -1;
    stPtr[0] = start[0];
    sO1[0] = -1;
    sO2[0] = -1;
    sT1[0] = 0;
    sT2[0] = 0;
    occ1[nums[0]] = 0;
    int sp = 1;
    while (sp > 0) {
      int d = sp - 1, u = stNode[d];
      if (stPtr[d] < start[u + 1]) {
        int p = stPtr[d]++;
        int v = to[p];
        if (v == stPar[d]) continue;
        int nd = d + 1, x = nums[v];
        int o1 = occ1[x], o2 = occ2[x];
        stNode[nd] = v;
        stPar[nd] = u;
        stPtr[nd] = start[v];
        sO1[nd] = o1;
        sO2[nd] = o2;
        sT1[nd] = top1;
        sT2[nd] = top2;
        if (o1 >= 0) {
          int sA = Math.max(top2, o1 + 1), sB = Math.max(top1, o2 + 1);
          int nt2 = sA;
          if (sB <= o1) nt2 = Math.min(sA, sB);
          top1 = Math.max(top1, o1 + 1);
          top2 = nt2;
        }
        occ2[x] = o1;
        occ1[x] = nd;
        dist[nd] = dist[d] + w[p];
        long len = dist[nd] - dist[top2];
        int cnt = nd - top2 + 1;
        if (len > bestLen || (len == bestLen && cnt < bestNodes)) {
          bestLen = len;
          bestNodes = cnt;
        }
        sp++;
      } else {
        if (d > 0) {
          int x = nums[u];
          occ1[x] = sO1[d];
          occ2[x] = sO2[d];
          top1 = sT1[d];
          top2 = sT2[d];
        }
        sp--;
      }
    }
    return new int[] {(int) bestLen, bestNodes};
  }
}
